const query = $json.query || {};
const search = (query.search || '').trim().toLowerCase();
const category = (query.category || 'all').toLowerCase();
const page = Math.max(1, parseInt(query.page) || 1);
const limit = Math.max(1, parseInt(query.limit) || 6);

// 模擬商品資料庫清單
const allProducts = [
  { id: 1, name: 'AI 智慧客服機器人模組', category: 'ai', price: 18000, stock: 99, description: '支援 OpenAI / Gemini 與上下文對話記憶，一鍵串接 LINE 與 Telegram。' },
  { id: 2, name: 'Supabase 向量知識庫 (RAG) 整合包', category: 'database', price: 25000, stock: 50, description: '結合 pgvector 實現私有文件語意檢索，提供零幻覺精準問答。' },
  { id: 3, name: 'Google Workspace 企業自動化套件', category: 'automation', price: 12000, stock: 120, description: '自動同步 Gmail、Google 試算表與 Google 雲端硬碟檔案。' },
  { id: 4, name: '電商訂單自動分流與發票通知', category: 'automation', price: 15000, stock: 80, description: '即時接收 Webhook 訂單、計算 5% 稅金並推播通知至營運群組。' },
  { id: 5, name: 'Pinecone 雲端向量資料庫高併發模組', category: 'database', price: 28000, stock: 35, description: 'Serverless 專用向量庫架構，支援毫秒級高併發語意比對。' },
  { id: 6, name: '多代理 (Multi-Agent) 協作系統', category: 'ai', price: 36000, stock: 20, description: '研究、審稿與報告產出多代理自主協同運作工作流。' },
  { id: 7, name: 'Postgres 資料庫定時輪詢與監控', category: 'database', price: 9900, stock: 200, description: '自動監控 pending 待處理數據，即時回寫 processing 狀態閉環。' },
  { id: 8, name: 'PDF 合約證書動態套版引擎 (GAS)', category: 'automation', price: 16000, stock: 65, description: 'Google Docs 佔位符動態替換，自動轉存唯讀 PDF 與 Drive 歸檔。' }
];

// 1. 分類與關鍵字篩選
let filtered = allProducts.filter(item => {
  const matchCategory = (category === 'all') || (item.category === category);
  const matchSearch = (!search) || 
    item.name.toLowerCase().includes(search) || 
    item.description.toLowerCase().includes(search);
  return matchCategory && matchSearch;
});

// 2. 伺服器端分頁計算
const totalItems = filtered.length;
const totalPages = Math.ceil(totalItems / limit) || 1;
const startIndex = (page - 1) * limit;
const paginatedItems = filtered.slice(startIndex, startIndex + limit);

return [{
  json: {
    statusCode: 200,
    response: {
      success: true,
      data: paginatedItems,
      pagination: {
        page: page,
        limit: limit,
        totalItems: totalItems,
        totalPages: totalPages
      }
    }
  }
}];
